  const cp = Array.from(source)
  const tokens = []
  let i = 0
  let line = 1
  let column = 1

  const at = (k = 0) => cp[i + k]
  const text = (from, to) => cp.slice(from, to).join('')

  /** Consumes one code point, keeping the position up to date. */
  function advance() {
    const c = cp[i]
    i += 1
    if (c === '\n') {
      line += 1
      column = 1
    } else if (c === '\t') {
      column += 4 - ((column - 1) % 4)
    } else {
      column += 1
    }
    return c
  }

  const fail = (l, c, reason) => {
    throw new ScanError(l, c, reason)
  }

  /**
   * Consumes a run of digits of one base, allowing a `_` that sits between two
   * of them. Returns whether at least one digit was consumed.
   */
  function digitRun(isDigitOfBase) {
    let seen = false
    for (;;) {
      if (isDigitOfBase(at())) {
        advance()
        seen = true
      } else if (seen && at() === '_' && isDigitOfBase(at(1))) {
        advance()
        advance()
      } else {
        return seen
      }
    }
  }

  /** Consumes what trails a broken number, so the message can name it all. */
  function badNumber(start, startLine, startColumn) {
    while (isIdentPart(at())) advance()
    fail(startLine, startColumn, `invalid number ${text(start, i)}`)
  }

  function scanNumber(start, startLine, startColumn) {
    if (at() === '0' && (at(1) === 'x' || at(1) === 'X' || at(1) === 'b' || at(1) === 'B' || at(1) === 'o' || at(1) === 'O')) {
      const marker = at(1)
      advance()
      advance()
      const of = marker === 'x' || marker === 'X' ? isHex : marker === 'b' || marker === 'B' ? isBin : isOct
