    } else {
      digitRun(isDigit)
      if (at() === '.' && isDigit(at(1))) {
        advance()
        digitRun(isDigit)
      }
      if (at() === 'e' || at() === 'E') {
        const sign = at(1) === '+' || at(1) === '-'
