 * The scanner. It turns UTF-8 source text into positioned tokens, or throws a
 * ScanError carrying the position and the reason of the first failure.
 */

export class ScanError extends Error {
  constructor(line, column, reason) {
    super(`${line}:${column}: ${reason}`)
    this.name = 'ScanError'
    this.line = line
    this.column = column
    this.reason = reason
  }
}

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])

const isDigit = (c) => c >= '0' && c <= '9'
const isLetter = (c) => (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')
const isIdentStart = (c) => c !== undefined && (isLetter(c) || c === '_')
const isIdentPart = (c) => c !== undefined && (isLetter(c) || isDigit(c) || c === '_')
const isHex = (c) => c !== undefined && (isDigit(c) || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F'))
const isBin = (c) => c === '0' || c === '1'
const isOct = (c) => c !== undefined && c >= '0' && c <= '7'

const PUNCT2 = ['==', '!=', '<=', '>=', '&&', '||', '->', '=>']
const PUNCT1 = ['+', '-', '*', '/', '%', '=', '<', '>', '!', '(', ')', '{', '}', '[', ']', ',', ';', '.']

/** Scans `source` and returns the list of tokens `{ line, column, kind, body }`. */
export function scan(source) {
  const cp = Array.from(source)
  const tokens = []
  let i = 0
  let line = 1
  let column = 1

  const at = (k = 0) => cp[i + k]
  const text = (from, to) => cp.slice(from, to).join('')

  /** Consumes one code point, keeping the position up to date. */
  function advance() {
    const c = cp[i]
    i += 1
    if (c === '\n') {
      line += 1
      column = 1
    } else if (c === '\t') {
      column += 4 - ((column - 1) % 4)
    } else {
      column += 1
    }
    return c
  }

  const fail = (l, c, reason) => {
    throw new ScanError(l, c, reason)
  }

  /**
   * Consumes a run of digits of one base, allowing a `_` that sits between two
   * of them. Returns whether at least one digit was consumed.
   */
  function digitRun(isDigitOfBase) {
    let seen = false
    for (;;) {
      if (isDigitOfBase(at())) {
        advance()
        seen = true
      } else if (seen && at() === '_' && isDigitOfBase(at(1))) {
        advance()
        advance()
      } else {
        return seen
      }
    }
  }

  /** Consumes what trails a broken number, so the message can name it all. */
  function badNumber(start, startLine, startColumn) {
    while (isIdentPart(at())) advance()
    fail(startLine, startColumn, `invalid number ${text(start, i)}`)
  }

  function scanNumber(start, startLine, startColumn) {
    if (at() === '0' && (at(1) === 'x' || at(1) === 'X' || at(1) === 'b' || at(1) === 'B' || at(1) === 'o' || at(1) === 'O')) {
      const marker = at(1)
      advance()
      advance()
      const of = marker === 'x' || marker === 'X' ? isHex : marker === 'b' || marker === 'B' ? isBin : isOct
      if (!digitRun(of)) badNumber(start, startLine, startColumn)
    } else {
      digitRun(isDigit)
      if (at() === '.' && isDigit(at(1))) {
        advance()
        digitRun(isDigit)
      }
      if (at() === 'e' || at() === 'E') {
        const sign = at(1) === '+' || at(1) === '-'
        if (isDigit(at(1)) || (sign && isDigit(at(2)))) {
          advance()
          if (sign) advance()
          digitRun(isDigit)
        }
      }
    }
    if (isIdentPart(at())) badNumber(start, startLine, startColumn)
    return { line: startLine, column: startColumn, kind: 'number', body: text(start, i) }
  }

  function scanString(startLine, startColumn) {
    advance() // the opening quote
    let value = ''
    for (;;) {
      if (i >= cp.length) fail(startLine, startColumn, 'unterminated string')
      const c = at()
      if (c === '"') {
        advance()
        return { line: startLine, column: startColumn, kind: 'string', body: JSON.stringify(value) }
      }
      if (c === '\n') fail(line, column, 'newline in string')
      if (c !== '\\') {
        value += advance()
        continue
      }
      const escLine = line
      const escColumn = column
      advance() // the backslash
      if (i >= cp.length) fail(startLine, startColumn, 'unterminated string')
      const e = at()
      if (e === '\n') fail(line, column, 'newline in string')
      const bad = () => fail(escLine, escColumn, `invalid escape \\${e}`)
      if (e === 'n') { advance(); value += '\n' }
      else if (e === 't') { advance(); value += '\t' }
      else if (e === 'r') { advance(); value += '\r' }
      else if (e === '\\') { advance(); value += '\\' }
      else if (e === '"') { advance(); value += '"' }
      else if (e === '0') { advance(); value += '\0' }
      else if (e === 'x') {
        if (!isHex(at(1)) || !isHex(at(2))) bad()
        advance()
        const h = advance() + advance()
        value += String.fromCharCode(parseInt(h, 16))
      } else if (e === 'u') {
        if (at(1) !== '{' || !isHex(at(2))) bad()
        let k = 2
        let digits = ''
        while (isHex(at(k))) {
          digits += at(k)
          k += 1
        }
        if (at(k) !== '}') bad()
        const code = parseInt(digits, 16)
        if (!Number.isFinite(code) || code > 0x10ffff) bad()
        for (let n = 0; n <= k; n += 1) advance()
        value += String.fromCodePoint(code)
      } else bad()
    }
  }

  function scanRawString(startLine, startColumn) {
    advance() // the r
    advance() // the opening quote
    const start = i
    for (;;) {
      if (i >= cp.length) fail(startLine, startColumn, 'unterminated string')
      if (at() === '"') {
        const value = text(start, i)
        advance()
        return { line: startLine, column: startColumn, kind: 'rawstring', body: JSON.stringify(value) }
      }
      advance()
    }
  }

  function skipBlockComment(startLine, startColumn) {
    advance()
    advance()
    let depth = 1
    while (depth > 0) {
      if (i >= cp.length) fail(startLine, startColumn, 'unterminated block comment')
      if (at() === '/' && at(1) === '*') {
        advance()
        advance()
        depth += 1
      } else if (at() === '*' && at(1) === '/') {
        advance()
        advance()
        depth -= 1
      } else advance()
    }
  }

  while (i < cp.length) {
    const c = at()
    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') {
      advance()
      continue
    }
    const startLine = line
    const startColumn = column
    const start = i

    if (c === '/' && at(1) === '/') {
      while (i < cp.length && at() !== '\n') advance()
      continue
    }
    if (c === '/' && at(1) === '*') {
      skipBlockComment(startLine, startColumn)
      continue
    }
    if (c === 'r' && at(1) === '"') {
      tokens.push(scanRawString(startLine, startColumn))
      continue
    }
    if (c === '"') {
      tokens.push(scanString(startLine, startColumn))
      continue
    }
    if (isIdentStart(c)) {
      while (isIdentPart(at())) advance()
      const body = text(start, i)
      tokens.push({ line: startLine, column: startColumn, kind: KEYWORDS.has(body) ? 'keyword' : 'ident', body })
      continue
    }
    if (isDigit(c)) {
      tokens.push(scanNumber(start, startLine, startColumn))
      continue
    }
    const pair = c + (at(1) ?? '')
    if (PUNCT2.includes(pair)) {
      advance()
      advance()
      tokens.push({ line: startLine, column: startColumn, kind: 'punct', body: pair })
      continue
    }
    if (PUNCT1.includes(c)) {
      advance()
      tokens.push({ line: startLine, column: startColumn, kind: 'punct', body: c })
      continue
    }
    fail(startLine, startColumn, `unexpected character ${c}`)
  }

  return tokens
}

export const KINDS = ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']
