/**
 * The command. `node src/cli.js tokens` prints every token of the source read
 * from standard input with its position, and `node src/cli.js stats` counts the
 * tokens by kind.
 */

import { readFileSync } from 'node:fs'
import { KINDS, ScanError, scan } from './scanner.js'

function main(argv) {
  const mode = argv.length === 1 ? argv[0] : undefined
  if (mode !== 'tokens' && mode !== 'stats') {
    process.stderr.write('error: usage: cli.js tokens|stats\n')
    return 2
  }

  let source = ''
  try {
    source = readFileSync(0, 'utf8')
  } catch {
    source = ''
  }

  let tokens
  try {
    tokens = scan(source)
  } catch (error) {
    if (!(error instanceof ScanError)) throw error
    process.stderr.write(`error: ${error.message}\n`)
    return 2
  }

  const lines = []
  if (mode === 'tokens') {
    for (const token of tokens) lines.push(`${token.line}:${token.column} ${token.kind} ${token.body}\n`)
  } else {
    const counts = new Map(KINDS.map((kind) => [kind, 0]))
    for (const token of tokens) counts.set(token.kind, counts.get(token.kind) + 1)
    for (const kind of KINDS) lines.push(`${kind} ${counts.get(kind)}\n`)
    lines.push(`total ${tokens.length}\n`)
  }
  process.stdout.write(lines.join(''))
  return 0
}

process.exitCode = main(process.argv.slice(2))
